Certainly! Here's a complete example of an HTML page that fulfills your requirements. The page includes a full-page `<canvas>` element with initial instructions, supports drag-and-drop image upload, disables click-to-upload after an image is loaded, and maintains drag-and-drop functionality.

### File Structure
```
index.html
styles.css
script.js
```

---

### `index.html`
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>Image Drag and Drop Canvas</title>
    <link rel="stylesheet" href="styles.css" />
</head>
<body>
    <canvas id="imageCanvas"></canvas>
    <script src="script.js"></script>
</body>
</html>
```

---

### `styles.css`
```css
/* Make the page and canvas fill the entire viewport */
html, body {
    margin: 0;
    padding: 0;
    height: 100%;
    width: 100%;
    overflow: hidden;
}

#imageCanvas {
    display: block;
    width: 100vw;
    height: 100vh;
    cursor: pointer; /* Indicate interactivity */
}
```

---

### `script.js`
```javascript
const canvas = document.getElementById('imageCanvas');
const ctx = canvas.getContext('2d');

let imageLoaded = false;
let currentImage = null;

// Set canvas size to fill the window
function resizeCanvas() {
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
    if (!imageLoaded) {
        drawInitialMessage();
    } else {
        drawImage();
    }
}

// Draw initial message
function drawInitialMessage() {
    ctx.fillStyle = "#f0f0f0";
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = "#333";
    ctx.font = "24px Arial";
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText("Drag an image here or click to upload", canvas.width / 2, canvas.height / 2);
}

// Draw the loaded image centered
function drawImage() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    if (currentImage) {
        // Fit image to canvas while maintaining aspect ratio
        const imgAspect = currentImage.width / currentImage.height;
        const canvasAspect = canvas.width / canvas.height;
        let drawWidth, drawHeight, offsetX, offsetY;

        if (imgAspect > canvasAspect) {
            // Image is wider
            drawWidth = canvas.width;
            drawHeight = canvas.width / imgAspect;
            offsetX = 0;
            offsetY = (canvas.height - drawHeight) / 2;
        } else {
            // Image is taller
            drawHeight = canvas.height;
            drawWidth = canvas.height * imgAspect;
            offsetX = (canvas.width - drawWidth) / 2;
            offsetY = 0;
        }

        ctx.drawImage(currentImage, offsetX, offsetY, drawWidth, drawHeight);
    }
}

// Handle window resize
window.addEventListener('resize', resizeCanvas);

// Initialize canvas size
resizeCanvas();

// Create a hidden file input for click-to-upload
const fileInput = document.createElement('input');
fileInput.type = 'file';
fileInput.accept = 'image/*';

// When user clicks on canvas, trigger file input if upload is enabled
let clickToUploadEnabled = true;

canvas.addEventListener('click', () => {
    if (clickToUploadEnabled) {
        fileInput.click();
    }
});

// Handle file selection
fileInput.addEventListener('change', (e) => {
    const file = e.target.files[0];
    if (file && file.type.startsWith('image/')) {
        loadImageFromFile(file);
    }
});

// Function to load image from file
function loadImageFromFile(file) {
    const reader = new FileReader();
    reader.onload = function(event) {
        const img = new Image();
        img.onload = () => {
            currentImage = img;
            imageLoaded = true;
            // Disable click-to-upload after first image
            clickToUploadEnabled = false;
            drawImage();
        };
        img.src = event.target.result;
    };
    reader.readAsDataURL(file);
}

// Drag-and-drop handlers
canvas.addEventListener('dragover', (e) => {
    e.preventDefault();
    e.stopPropagation();
    // Optional: add visual feedback
    canvas.style.border = '2px dashed #666';
});

canvas.addEventListener('dragleave', (e) => {
    e.preventDefault();
    e.stopPropagation();
    // Remove visual feedback
    canvas.style.border = '';
});

canvas.addEventListener('drop', (e) => {
    e.preventDefault();
    e.stopPropagation();
    canvas.style.border = '';

    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
        const file = e.dataTransfer.files[0];
        if (file.type.startsWith('image/')) {
            loadImageFromFile(file);
        }
    }
});

// Initial draw
drawInitialMessage();
```

---

### Summary of Functionality:
- The page loads with a full-page `<canvas>` displaying a message.
- Clicking on the canvas opens a file dialog to upload an image (click-to-upload enabled initially).
- Dragging and dropping an image onto the canvas loads it.
- After the first image is loaded, click-to-upload is disabled, but drag-and-drop remains functional.
- The image is scaled to fit the canvas while maintaining aspect ratio and centered.

Feel free to customize styles, messages, or behavior further!

